import { isInstanceOf } from '@threlte/core';
import { onDestroy } from 'svelte';
import { useStudio } from '../../internal/extensions';
import { studioObjectsRegistryScope } from './types';
export const useStudioObjectsRegistry = () => {
    const { useExtension } = useStudio();
    const extension = useExtension(studioObjectsRegistryScope);
    const objects = $derived(extension.state.objects ?? new Set());
    const isOrIsChildOfStudioObject = (object) => {
        if (!extension.state.objects)
            return false;
        if (extension.state.objects.has(object))
            return true;
        if (object.parent)
            return isOrIsChildOfStudioObject(object.parent);
        return false;
    };
    const studioObjectRef = () => {
        const objects = [];
        let ref = $state();
        const studioObjectsRegistry = useStudioObjectsRegistry();
        $effect(() => {
            if (!ref)
                return;
            objects.push(ref);
            ref.traverse((node) => {
                if (isInstanceOf(node, 'Object3D')) {
                    objects.push(node);
                }
                node.userData.ignoreOverrideMaterial = true;
            });
            new Set(objects).forEach((object) => {
                studioObjectsRegistry.addObject(object);
            });
        });
        onDestroy(() => {
            new Set(objects).forEach((object) => {
                studioObjectsRegistry.addObject(object);
            });
        });
        return {
            get ref() {
                return ref;
            },
            set ref(value) {
                ref = value;
            }
        };
    };
    return {
        /** @reactive */
        get objects() {
            return objects;
        },
        addObject: extension.addObject,
        removeObject: extension.removeObject,
        isOrIsChildOfStudioObject,
        studioObjectRef
    };
};
